public class LiveProjectSource extends BoundedSource<GCPProject> {
  private static final long SIZE_ESTIMATE = 200;
  private static final String DELETE_PREFIX = "DELETE";
  private String orgId;

  /**
   * Constructor for LiveProjectSource.
   * @param orgId The ID of the organization from which we read the projects list.
   *  Set as null to read from all visible orgs.
   */
  public LiveProjectSource(String orgId) {
    this.orgId = orgId;
  }

  /**
   * Getter for the field orgId.
   * @return The ID of the organization whose projects are to be read.
   */
  public String getOrgId() {
    return this.orgId;
  }

  /**
   * This function just returns the same source as a list, and does not
   * actually split the load into several bundles.
   * @param desiredBundleSizeBytes The desired bundle size. Not used.
   * @param options Pipeline options. Not used
   * @return A list containing this source as its only element.
   */
  @Override
  public List<LiveProjectSource> splitIntoBundles(
      long desiredBundleSizeBytes, PipelineOptions options) throws Exception {
    List<LiveProjectSource> projectSources = new ArrayList<>(1);
    projectSources.add(this);
    return projectSources;
  }

  /**
   * Currently returns a hardcoded value.
   * Get the estimated size of the data that will be read by this source.
   * @param options Pipeline options. Not used.
   * @return The size estimate of the data to be read by this source.
   */
  @Override
  public long getEstimatedSizeBytes(PipelineOptions options) throws Exception {
    return SIZE_ESTIMATE;
  }

  /**
   * This function does not give any guarantees about whether its output will be sorted or not.
   * @param options Pipeline options. Not used.
   * @return Returns true if the source's output is always sorted. False otherwise.
   */
  @Override
  public boolean producesSortedKeys(PipelineOptions options) throws Exception {
    return false;
  }

  /**
   * Create a new reader that will read from this source.
   * @param options Pipeline options. Not used.
   * @return A BoundedReader object to read from this source.
   */
  @Override
  public BoundedReader<GCPProject> createReader(PipelineOptions options) throws IOException {
    return new LiveProjectReader(this);
  }

  /**
   * Validate whether this source can function or not.
   */
  @Override
  public void validate() {}

  /**
   * Get the default coder to use for this source's output.
   * @return The default coder to use for this source's output.
   */
  @Override
  public Coder<GCPProject> getDefaultOutputCoder() {
    return SerializableCoder.of(GCPProject.class);
  }

  /** Reader for LiveProjectSource */
  public static class LiveProjectReader extends BoundedReader<GCPProject> {
    private LiveProjectSource source;
    private List<GCPProject> projects;
    private String nextPageToken;

    /**
     * Getter for the projects field.
     * @return Return the projects currently in the reader's queue.
     */
    List<GCPProject> getProjects() {
      return projects;
    }

    /**
     * Getter for the nextPageToken field.
     * @return Return the nextPageToken to be used in the
     * next request to get the next page of projects.
     */
    String getNextPageToken() {
      return nextPageToken;
    }

    /**
     * Construct a LiveProjectReader object.
     * @param source The source this reader is supposed to read from.
     */
    public LiveProjectReader(LiveProjectSource source) {
      this.source = source;
      this.projects = new ArrayList<>();
      this.nextPageToken = null;
    }

    /**
     * Initialize the reader so it can begin reading files.
     * @return True if the initialization succeeded. False otherwise.
     */
    @Override
    public boolean start() throws IOException {
      return refreshProjects(null);
    }

    /**
     * Advance the reader so it can read the next file in the queue.
     * @return True if there are still more files to be read. False otherwise.
     */
    @Override
    public boolean advance() throws IOException {
      if (this.projects.size() > 1) {
        this.projects.remove(0);
        return true;
      } else if (this.projects.size() == 1) {
        this.projects.remove(0);
        // if token is null the last page read was the last page to be read.
        return (this.nextPageToken != null) && refreshProjects(this.nextPageToken);
      }
      return false;
    }

    /**
     * Get the next file in queue.
     * @return A GCPProject object representing the project that is read.
     * @throws NoSuchElementException If the file can't be read from the CRM API.
     */
    @Override
    public GCPProject getCurrent() throws NoSuchElementException {
      if (this.projects.isEmpty()) {
        throw new NoSuchElementException("No more GCPProject objects");
      }
      return this.projects.get(0);
    }

    /**
     * Close this reader.
     */
    @Override
    public void close() throws IOException {}

    /**
     * Return the source this reader is reading from.
     * @return The source this reader is reading from.
     */
    @Override
    public BoundedSource<GCPProject> getCurrentSource() {
      return this.source;
    }

    private boolean refreshProjects(String nextPageToken) throws IOException {
      ListProjectsResponse projectListResponse;
      Projects.List projectsList;
      try {
        projectsList = GCPProject.getProjectsApiStub().list();
        if (nextPageToken != null) {
          projectsList = projectsList.setPageToken(nextPageToken);
        }
        if (source.getOrgId() != null) {
            projectsList = projectsList
                .setFilter("parent.type:organization parent.id:" + source.getOrgId());
        }
        projectListResponse = projectsList.execute();
      } catch (GeneralSecurityException gse) {
        throw new IOException("Cannot get projects. Access denied");
      }
      List<Project> projects = projectListResponse.getProjects();

      for (Project project : projects) {
        String orgId = null;
        if (project.getParent() != null) {
          orgId = project.getParent().getId();
        }
        if (project.getLifecycleState() == null
            || project.getLifecycleState().startsWith(DELETE_PREFIX)) {
          continue;
        }
        this.projects.add(new GCPProject(project.getProjectId(), orgId, project.getName()));
      }
      this.nextPageToken = projectListResponse.getNextPageToken();

      return !this.projects.isEmpty();
    }
  }
}
src/main/java/com/google/cloud/security/scanner/primitives/GCPProject.java
public class GCPProject implements PoliciedObject {
  private static Projects projectApiStub;

  private static final RateLimiter rateLimiter = CloudUtil.getAdminApiRateLimiter();

  private String name;
  private String id;
  private String orgId;

  /**
   * Setter for the CRM Projects API stub.
   * @param project The CRM Projects API stub.
   */
  public static synchronized void setProjectsApiStub(Projects project) {
    GCPProject.projectApiStub = project;
  }

  /**
   * Return the Projects api object used for accessing the Cloud Resource Manager Projects API.
   * @return Projects api object used for accessing the Cloud Resource Manager Projects API
   * @throws GeneralSecurityException Thrown if there's a permissions error.
   * @throws IOException Thrown if there's an IO error initializing the API object.
   */
  public static synchronized Projects getProjectsApiStub()
      throws GeneralSecurityException, IOException {
    if (projectApiStub != null) {
      return projectApiStub;
    }
    HttpTransport transport;
    GoogleCredential credential;
    JsonFactory jsonFactory = JacksonFactory.getDefaultInstance();
    transport = GoogleNetHttpTransport.newTrustedTransport();
    credential = GoogleCredential.getApplicationDefault(transport, jsonFactory);
    if (credential.createScopedRequired()) {
      Collection<String> scopes = CloudResourceManagerScopes.all();
      credential = credential.createScoped(scopes);
    }
    projectApiStub = new CloudResourceManager
        .Builder(transport, jsonFactory, credential)
        .build()
        .projects();
    return projectApiStub;
  }

  /**
   * Construct a GCPProject object with only the project ID.
   * Other fields are left as null.
   * @param id The ID of the project. This is different from the project name.
   * @throws IllegalArgumentException If the project id is null.
   */
  public GCPProject(String id) throws IllegalArgumentException {
    this(id, null, null);
  }

  /**
   * Construct a GCPProject object with the project and org IDs.
   * @param id The ID of the project. This is different from the project name.
   * @param orgId The ID of the org this project belongs to.
   * @throws IllegalArgumentException If the project id is null.
   */
  public GCPProject(String id, String orgId) throws IllegalArgumentException {
    this(id, orgId, null);
  }

  /**
   * Construct a GCPProject object with the project and org IDs, and the project name.
   * @param id The id of the project.
   * @param orgId The id of the org this project belongs to.
   * @param name The display name of the project.
   * @throws IllegalArgumentException If the project id is null.
   */
  public GCPProject(String id, String orgId, String name) throws IllegalArgumentException {
    if (id == null) {
      throw new IllegalArgumentException("GCPProject's id cannot be null");
    }
    if (orgId == null) {
      orgId = "";
    }
    if (name == null) {
      name = "";
    }
    this.id = id;
    this.orgId = orgId;
    this.name = name;
  }

  /**
   * @return The display name of the project.
   */
  public String getName() {
    return this.name;
  }

  /**
   * @return The ID of the org this project belongs to.
   */
  public String getOrgId() {
    return this.orgId;
  }

  /**
   * @return The ID of the project.
   */
  @Override
  public String getId() {
    return this.id;
  }

  /**
   * Get the IAM policy binding this project.
   * @return The GCPResourcePolicy object which represents the policy binding this project.
   * @throws IOException Thrown if there's an IO error reading the policy.
   * @throws GeneralSecurityException Thrown if there's a permissions error reading the policy.
   */
  @Override
  public GCPResourcePolicy getPolicy() throws IOException, GeneralSecurityException {
    Map<String, List<String>> bindings = new HashMap<>();
    Policy policy = null;

    rateLimiter.acquire();

    try {
      policy = getProjectsApiStub()
          .getIamPolicy(this.id, new GetIamPolicyRequest())
          .execute();
    } catch (GeneralSecurityException gse) {
      throw new GeneralSecurityException(
          "Cannot fetch IAM policy for project + " + id + "\nMessage: " + gse.getMessage()
      );
    }
    if (policy != null && policy.getBindings() != null) {
      for (Binding binding : policy.getBindings()) {
        bindings.put(binding.getRole(), binding.getMembers());
      }
      return new GCPResourcePolicy(this, bindings);
    }
    return null;
  }

  /**
   * Set the IAM policy that will bind this project. This requires the "Project Owner"
   * role to be added to the service account.
   * @param sourceGCPResourcePolicy The policy this project is to be bound to.
   * @throws IOException Thrown if there's an IO error setting the policy.
   * @throws GeneralSecurityException Thrown if there's a permissions error setting the policy.
   */
  @Override
  public void setPolicy(GCPResourcePolicy sourceGCPResourcePolicy)
      throws IOException, GeneralSecurityException {
    Policy policy = new Policy();
    List<Binding> bindings = new ArrayList<>(sourceGCPResourcePolicy.getBindings().size());
    SetIamPolicyRequest request = new SetIamPolicyRequest();

    rateLimiter.acquire();

    for (PolicyBinding sourceBinding : sourceGCPResourcePolicy.getBindings()) {
      Binding binding = new Binding();
      binding.setRole(sourceBinding.getRole());
      binding.setMembers(sourceBinding.getMembers());
      bindings.add(binding);
    }
    policy.setBindings(bindings);
    request.setPolicy(policy);
    getProjectsApiStub().setIamPolicy(this.id, request).execute();
  }

  /**
   * Comparator for GCPProject objects. It only checks for equality of the project IDs.
   * @param o The object to compare with.
   * @return True if they have the same project ID, false otherwise.
   */
  @Override
  public boolean equals(Object o) {
    return (o instanceof GCPProject) && ((GCPProject) o).id.equals(this.id);
  }

  /**
   * hashCode method which only respects the project's id.
   * @return Hash code for this object.
   */
  @Override
  public int hashCode() {
    return this.id.hashCode();
  }

  /**
   * toString method which only returns the id of the project.
   * @return The id of the project.
   */
  @Override
  public String toString() {
    return this.id;
  }
}
